item.content:encoded:
/** New Mega Menu **/
body.admin-bar #page,
body.admin-bar #masthead {
	margin-top: 32px;
}
header {
	box-shadow: -1px 3px 21px -11px rgba(0,0,0,0.75);
	-webkit-box-shadow: -1px 3px 21px -11px rgba(0,0,0,0.75);
	-moz-box-shadow: -1px 3px 21px -11px rgba(0,0,0,0.75);
}

.desktop-navigation ul {
	margin: unset;
	list-style: none;
	padding: unset;
}

.desktop-navigation > ul > li > a {
	text-decoration: none;
	color: #004269;
	font-size: 16px;
}

.desktop-navigation a {
	text-decoration: none;
	color: #004269;
}

.desktop-navigation > ul > li:hover > a {
	font-weight: bold;
}

.desktop-navigation ul li:hover .mega-menu {
	display: flex;
	position: absolute;
	padding-top: 40px;
	width: 100%;
}

.desktop-navigation .mega-menu {
	display: none;
	padding: 50px calc(max((100vw - 1100px) / 2, 1rem));
	left: 0;
	gap: 20px;
}

.desktop-navigation > ul {
	display: flex;
	gap: 20px;
	padding: unset;
	margin-left: 50px;
}

.site .site-header {
	justify-content: unset;
}

.site .site-header .site-contact {
	margin-left: auto;
}

.desktop-navigation .mega-menu .services-list li {
	margin: 10px 0px;
}

.desktop-navigation .mega-menu .services-list li:hover {
	cursor: pointer;
}

.desktop-navigation .mega-menu .services-list li:hover + .site-main {
	opacity: 0.5 !important;
}

.desktop-navigation .mega-menu .services-list li {
	background-color: #184166;
	padding: 10px;
	border-radius: 10px;
	width: 100%;
	display: flex;
	height: max-content;
	align-items: center;
	gap: 10px;
	position: relative;
}

.desktop-navigation .mega-menu .services-list li a {
	color: white;
	font-weight: bold;
	font-size: 18px;
	position: absolute;
	left: 0;
	width: 100%;
	height: 100%;
	display: flex;
	align-items: center;
	padding-left: 60px;
}

.desktop-navigation .mega-menu .services-list li img {
	max-width: 40px;
}

.desktop-navigation .mega-menu .services-list li:hover {
	background-color: white;
}

.desktop-navigation .mega-menu .mega-menu-right {
	background-color: white;
	border-radius: 10px;
	padding: 20px;
	width: 66%;
	display: flex;
	justify-content: center;
	align-items: center;
}

.services-list {
	display: flex;
	flex-direction: column;
	justify-content: space-between;
	width: 30%;
}

.mega-menu-right > div {
	justify-content: center;
	align-items: center;
}

.mega-menu-right > div > ul {
	display: flex;
	flex-direction: column;
	justify-content: space-between;
	gap: 20px;
}

.mega-menu-right > div img {
	max-width: 400px;
}

.mega-menu-right > div svg {
	max-width: 20px;
	height: unset
}

.mega-menu-right > div > ul > li {
	display: flex;
	align-items: center;
	gap: 10px;
}

.cloud-phone-systems-mega-content, .smartvoice-mega-content, .whatsapp-mega-content, .internet-mega-content, .wifi-mega-content, .mobile-mega-content, .it-mega-content, .smart-mega-content {
	display: none;
}

.cloud-phone-systems-menu a, .cloud-phone-systems-mega-content svg path, .cloud-phone-systems-mega-content a:hover {
	color: #76C0FF !important;
	fill: #76C0FF !important;
}

.smartvoice-menu a, .smartvoice-mega-content svg path, .smartvoice-mega-content a:hover {
	color: #CC289C !important;
	fill: #CC289C !important;
}

.whatsapp-menu a, .whatsapp-mega-content svg path, .whatsapp-mega-content a:hover {
	color: #2ACC63 !important;
	fill: #2ACC63 !important;
}

.internet-menu a, .internet-mega-content svg path, .internet-mega-content a:hover {
	color: #EE561D !important;
	fill: #EE561D !important;
}

.wifi-menu a, .wifi-mega-content svg path, .wifi-mega-content a:hover {
	color: #FFCE00 !important;
	fill: #FFCE00 !important;
}

.mobile-menu a, .mobile-mega-content svg path, .mobile-mega-content a:hover {
	color: #24D19C !important;
	fill: #24D19C !important;
}

.it-menu a, .it-mega-content svg path, .it-mega-content a:hover {
	color: #D5ACF8 !important;
	fill: #D5ACF8 !important;
}

.smart-menu a, .smart-mega-content svg path, .smart-mega-content a:hover {
	color: #EC5F59 !important;
	fill: #EC5F59 !important;
}

.mega-menu-right div ul li a:hover {
	font-weight: bold;
	cursor: pointer;
}

@media (max-width: 991px) {
	.desktop-navigation {
		display: none;
	}
}

@media (min-width: 991px) {
	.mobile-navigation {
		display: none;
	}
}

/* Homepage Padding overright */

/* .site-header {
top: unset !important
} */

#industries > .gb-inside-container {
	padding: 7rem 0 !important;
}

#industries > .gb-inside-container > .gb-container {
	padding: unset;
}

.accolades-grid > .gb-grid-column {
	display: flex;
	justify-content: center;
	align-items: stretch;
}

.wpmapblockrender {
	border-bottom: 0!important;
}

.home-header-img-container {
	height: auto!important;
}

.rounded-img-sm > img {
	border-radius: 16px;
}

@media (min-width: 783px) {
	.gc-marquee {
		animation: cssmarquee 100s linear infinite;
		animation-delay: -50s;
		width: 5880px;
		height: 117px;
		gap: 2rem!important;
		padding: 1rem 2rem 1rem 0!important;
		top: 0!important;
	}

	.gc-marquee-2 {
		animation-delay: 50s;
	}


	.clients-marquee .gc-marquee {
		animation: cssmarquee 36s linear infinite;
		animation-delay: -18s;
		width: 3880px;
		height: 117px;
		gap: 2rem!important;
		padding: 1rem 2rem 1rem 0!important;
		top: 0!important;
	}

	.clients-marquee .gc-marquee.marquee-2 {
		animation-delay: 0s!important;
	}
}

@media (max-width: 782px) {
	.gc-marquee {
		width: 5880px;
		animation: cssmarquee 100s linear infinite;
		animation-delay: -50s;
	}

	.gc-marquee .gc-marquee-item {
		width: 100px!important;
		height: 100px!important;
	}
}

.sub-menu li a i {
	color: #f06120;
	display: contents;
}

@media (max-width: 783px) {
	.wp-block-media-text .wp-block-media-text__content {
		padding: 2rem 0;
	}

	.industry-contact-text {
		margin: 0 0 4rem 0;
	}
}

.clients-marquee .gc-marquee {
	width: 2700px;
}

.home-header-img-1 {
	max-width: 80vw!important;
}

.wp-block-media-text__media img {
	width: auto;
	max-width: 100%;
}

.home-header-img-center {
	width: 100%;
}

.home-header-img-center img {
	max-height: 50vh;
	width: auto;
	margin: auto;
}

@media (min-width: 783px) {
	.home-header-img-right {
		bottom: -140px!important;
	}

	.home-header-img-left {
		bottom: -150px!important;
	}
}

.testimonial-slider .slick-track {
	height: 500px;
}

.testimonial-slider .slick-list {
	height: 550px;
}

.site-phone-number a, .fone-contact-details a {
	text-decoration: none;
}

/* video styling */

.video-grid iframe, .case-studies iframe {
	border-radius: 25px;
}

@media (max-width: 700px) {
	.video-grid {
		margin-top: 20px;
	}
}

.video-case-study-section .gb-inside-container {
	padding-top: 10px;
}

.video-case-study-section {
	min-height: 0px;
}

.no-margin {
	margin: 0!important;
}

/*** Footer hover ***/
.site-footer ul.menu li a:hover {
	color: #f06120;
} 

/*** Mobile Footer ***/

@media (max-width: 700px) {
	.footer-mobile {
		flex-direction: column;
	}
}

/*** Mobile optimisation ***/

.blog-header {
	text-align: center;
}

@media (max-width: 400px) {
	.gb-container-2e0b67e8 {
		min-height: 650px;
	}

	.blog-header {
		text-align: center;
	}}

@media (max-width: 700px) {
	.footer-mobile h4 {
		margin-bottom: 2px;
		margin-top: 5px;
	}}

@media (max-width: 1000px) {
	.fone-contact-details {
		margin-bottom: 2em;
	}}

.mb-2 {
	margin-bottom: 2rem!important;
}

/* form select fix */
.wpcf7-select {
	height: 40px!important;
	padding: 0 0.5rem;
	color: #777;
	border-radius: 5px;
}
.orange-link {
	color: #404040;
}
.orange-link:visited {
	color: #404040;
}
.orange-link:hover {
	color: #f06120;
}
.orange-link-white {
	color: white;
}
.orange-link-white:visited {
	color: white;
}
.orange-link-white:hover {
	color: #f06120;
}
.contact-form .form-submit > p,
.submit-row > p {
	display: flex;
	flex-direction: row-reverse;
}
.request-quote-form {
	grid-template-areas: unset !important;
}
#usercounts {
	color: white;
}
#request-a-quote-range {
	background-color: white;
}

/* job listings */

div.job_listings {
	background: rgba(255,255,255,0.9);
	border-radius: 5px;
	padding: 2em;	
}
form.wpcf7-form .request-quote-form input:not([type=range]) {
	height: 40px !important;
}
#request-a-quote-range {
	height: 40px;
}
form.wpcf7-form .request-quote-form datalist {
	top: -17px !important;
}
@media (max-width:768px) {
	#contact-form-details li {
		justify-content: center;
	}
	#contact-form-details li > span {
		width: fit-content;
		text-align: center;
	}
}
@media (max-width:768px) {
	.footer-h4 {
		margin-bottom: 0;
	}
	.dropdown-menu h4 {
		display: block;
		width: fit-content;
		transition-duration: 0.5s;
		padding-right: 30px;
		background-size: 15px;
		background-repeat: no-repeat;
		background-position: right center;
		background-image: url(https://fonetech.uk/wp-content/uploads/arrow-orange.svg);
	}

	.dropdown-menu h4:hover {
		cursor: pointer;
	}
	.dropdown-menu .widget {
		margin: unset;
	}

	.dropdown-menu ul {
		position: relative;
		transition: all 0.5s ease;
		margin-top: 1rem;
		left: 0;
		display: none;
		padding-bottom: 1rem !important;
	}

	.dropdown-menu1 h4:hover + .widget ul {
		visibility: visible;
		opacity: 1;
		display: block;
	}

	.dropdown-menu1 ul li ul li {
		clear: both;
		width: 100%;
	}
	.footer-mobile {
		padding-bottom: 30px;
	}
}
figure.alignleft {
	margin-right: 0 !important;
}
.page-id-503 .wpcf7-response-output {
	color: white !important;
}
form.wpcf7-form .request-quote-form datalist {
	top: -20px !important;
}
.remove-background {
	background-color: unset !important;
}
@media (min-width:769px) {
	.mobile-social-footer {
		display: none;
	}
}

#request-a-quote-range br,
{
	display: none;
}
.users-slider {
	display: flex;
}
#usercounts {
	width: 100%;
	padding: 0 0.8rem;
	margin-left: 0;
	list-style: none;
	display: flex;
	font-size: 12px;
	margin-bottom: 0;
	justify-content: space-between;
}
#usercounts li > p {
	margin-bottom: 0;
}
.usercount-number-container {
	display: flex;
	align-items: center;
	margin-bottom: 5px;
}
.usercount-title {
	margin-left: 0.8rem;
	opacity: 0;
}
.usercount-number-container p {
	margin-bottom: 0;
}
.quote-step-container {
	color: white;
	text-align: center;
}
@media (max-width:1200px) {
	.awards-images img {
		width: 150px;
	}
}
@media (max-width:1024px) {
	#awards-desktop {
		transform: translate3d(0,150px,0);
	}
}
@media (max-width:800px) {
	#awards-desktop {
		transform: translate3d(0,200px,0);
	}
}

@media (max-width: 1100px) {
	#header-container {
		padding: 0;
	}
}

/* Customer Area Accordian */

.hidden-content {
	max-height: 0 !important;
}

.expand-content {
	max-height: 1500px;
	overflow: hidden;
	transition: max-height 1s ease-in-out;
}

#expand-button:hover {
	cursor: pointer;
	color: #f06120 !important;
}

.customer-area-item-grid {
	width: 100%;
	justify-content: space-between;
	color: #ffffff;
}

.customer-area-item-text {
	margin: unset;
}

.never-display {
	display: none;
}

.margin-unset {
	margin: unset !important;
}

@media (max-width: 782px) {
	.text-hidden-mobile .gb-button-text {
		display: none;
	}
	.text-hidden-mobile {
		font-size: 25px !important;
		padding: 10px !important;
		border-radius: 10px !important;
	}
	.download-container {
		padding: 10px !important;
		border-radius: 10px !important;
	}
}

@media (max-width: 768px) {
	.mobile-hidden-text {
		display: none;
	}
}

@media (max-width: 280px) {
	.mobile-pdf-icon {
		display: none;
		width: 0%;
	}
	.text-hidden-mobile {
		font-size: 15px !important;
	}
	.download-container {
		padding: 5px !important;
		border-radius: 10px !important;
	}
	.customer-area-item-grid > .gb-grid-column:first-child {
		width: 0% !important;
	}
}

/* New Marquee */

/* .scroller {
max-width: 100vw;
}

.scroller__inner {
padding-block: 1rem;
display: flex;
flex-wrap: nowrap;
gap: 1rem;
overflow: auto;
}

.scroller__inner > img {
height: 50px;
padding: 10px
} */

/* @media (min-width: 0px) { */
.scroller {
	max-width: 100%;
	opacity: 1 !important;
}

.scroller__inner {
	padding-block: 1rem;
	display: flex;
	flex-wrap: wrap;
	gap: 1rem;
	opacity: 1 !important;
}

.scroller__inner > img {
	height: 50px;
	padding: 10px;
	opacity: 1 !important;
}

.scroller[data-animated="true"] .scroller__inner {
	max-width: 1000%;
}

.scroller[data-animated="true"] {
	overflow: visible;
}

.scroller[data-animated="true"] .scroller__inner {
	width: max-content;
	flex-wrap: nowrap;
	animation: scroll var(--_animation-duration, 40s)
		var(--_animation-direction, forwards) linear infinite;
}

.scroller[data-direction="right"] {
	--_animation-direction: reverse;
}

.scroller[data-direction="left"] {
	--_animation-direction: forwards;
}

.scroller[data-speed="fast"] {
	--_animation-duration: 30s;
}

.scroller[data-speed="average"] {
	--_animation-duration: 60s;
}

.scroller[data-speed="slow"] {
	--_animation-duration: 90s;
}

@keyframes scroll {
	to {
		transform: translate(calc(-50% - 0.5rem));
	}
}
/* } */

/* general styles */

.tag-list {
	margin: 0;
	padding-inline: 0;
	list-style: none;
}

.tag-list li {
	padding: 1rem;
	background: var(--clr-primary-400);
	border-radius: 0.5rem;
	box-shadow: 0 0.5rem 1rem -0.25rem var(--clr-primary-900);
}

/* for testing purposed to ensure the animation lined up correctly */
.test {
	background: red !important;
}

/* Phone Systems Carousel */

@media (max-width: 768px) {
	.phone-systems-carousel figure img{
		height: auto !important;
		width: auto !important;
		opacity: 1 !important;
	}
}

.site-footer {
	text-transform: none;
}

#menu-item-502, #menu-item-1352 {
	text-transform: none;
}

.get-in-touch h4 {
	text-transform: none;
}

/* Dark Web */

#dark-web-monitoring iframe {
	height: 250px;
}

/* Microsoft Backup */

.microsoft-backup .gb-inside-container .wp-block-columns:where(.wp-block-columns.is-layout-flex) {
	gap: 8em;
}

@media (max-width: 769px) {
	.microsoft-backup .gb-inside-container .wp-block-columns:where(.wp-block-columns.is-layout-flex) {
		gap: 2em;
	}
}

.footer-email {
	text-transform: none;
}

/* About Page */

@media (max-width: 769px) {
	.centralised-text-on-mobile {
		text-align: center;
	}
}

#omnichatWidget .msgboxxlauncher__close{
	font-size: unset !important;
}

.msgboxxlauncher_cta span{
	font-size: unset !important;
}

.msgboxxlauncher img {
	height: 60px;
}

.gotalk-ai-gradient {
	background: rgb(237,212,118);
	background: -moz-linear-gradient(45deg, rgba(237,212,118,1) 0%, rgba(183,72,166,1) 23%, rgba(124,77,255,1) 100%);
	background: -webkit-linear-gradient(45deg, rgba(237,212,118,1) 0%, rgba(183,72,166,1) 23%, rgba(124,77,255,1) 100%);
	background: linear-gradient(45deg, rgba(237,212,118,1) 0%, rgba(183,72,166,1) 23%, rgba(124,77,255,1) 100%);
	filter: progid:DXImageTransform.Microsoft.gradient(startColorstr="#edd476",endColorstr="#7c4dff",GradientType=1);
}

.margin-unset {
	margin: unset !important;
}

/****/

.fone-smart-voice-image {
	width: 1000px;
}

@media (max-width: 1025px) {
	.fone-smart-voice-image {
		width: auto;
	}
}

figure.is-type-video iframe {
	margin-bottom: -6px;
	border-radius: 25px;
}

figure.marketing-video iframe {
	border: 2px solid #cc299c;
	margin-bottom: -6px;
	border-radius: 2em
}

figure.marketing-video {
	display: flex;
	justify-content: center;	
}

.no-border iframe {
	border: none!important;
} 

.text-image-hover-container img {
	border-radius: 25px;
}

.text-image-hover-container {
	border-radius: 25px;
	overflow: hidden;
}

.side-by-side-rounded-corners img {
	border-radius: 25px;
}

@media (min-width: 1025px) {
	.site .site-header nav, .site .site-header .site-branding, .site .site-header .site-contact {
		width: unset;
	}
	.site .site-header li a ion-icon {
		font-size: 25px;
		color: #f06120;
	}
}

@media (max-width: 1140px) {
	.site .site-header > nav > div > ul > li > a > ion-icon {
		display: none;
	}
}

@media (min-width: 1140px) {
	.site .site-header li a ion-icon {
		margin-right: 10px
	}
}

.cdp-copy-alert-success {
	display: none !important;
}

/*** Footer & Header Updates ***/

.site-footer > section {
	max-width: unset;
}

.site-footer > section > .gb-container > .gb-inside-container {
	max-width: 1600px;
	font-size: 12px;
	padding: 0 20px
}

.site-header {
	font-size: 14px;
}

.site-branding svg {
	overflow: visible;
}

@media (min-width: 1025px) {
	.site
	.site-header .menu-item-has-children:focus .sub-menu, .site
	.site-header .menu-item-has-children:hover .sub-menu {
		justify-content: center;
	}
}


/** mobile menu updates */

@media (max-width: 1024px) {
	.main-navigation ul.menu.nav-menu li a ion-icon.md {
		display: inline-block;
		color: #f06120;
		padding: 0 1em 0 0;
	}

	.main-navigation ul.nav-menu {
		overflow-y: scroll;
		height: 100vh;
		display: block;
	}

	.main-navigation ul ul.sub-menu {
		box-shadow: none;
		transition: none;
		transform: none;
		width: 100%;
		position: relative;
		top: auto;
		left: auto;
		z-index: 99999;
		padding: 0 2em;
		display: block;
	}

	.main-navigation ul.menu.nav-menu li a {
		opacity: 1;
		padding: 1em;
	}

	.main-navigation > div > ul > li.menu-item {
		flex-direction: column;
		align-items: flex-start;
	}

	.main-navigation > div > ul > li.menu-item > ul > li {
		flex-direction: column;
		align-items: flex-start;
	}

	.main-navigation > div > ul > li.menu-item > ul > li > a {
		width: 100%;
		padding: 0.5em;
	}

	.main-navigation > div > ul > li.menu-item:hover ul li {
		left: auto;
	}
}

.slick-dots li button:before {
	width: 40px !important;
	height: 40px !important;
	color: #fff !important
}

/** Footer updates with products column **/
.site-footer .gb-grid-column .gb-grid-column {
	width: 16%;
}

.site-footer .gb-grid-wrapper > .gb-grid-column-77b04b02 {
	width: 100%;
}

.site-footer .gb-grid-wrapper-a7d86527 {
	display: flex;
	flex-wrap: wrap;
	justify-content: center;
	width: 100%;
}

@media (max-width: 1140px) {
	.site-footer .gb-grid-wrapper > .gb-grid-column-e3d34b13 {
		width: 100%;
	}
	.site-footer .gb-grid-wrapper > .gb-grid-column-77b04b02 {
		width: 100%;
	}
	.site-footer .gb-container-e3d34b13 > .gb-inside-container {
		padding-left: 0%;
	}
}

@media (max-width: 925px) {
	.site-footer .gb-grid-column .gb-grid-column {
		width: 50%;
	}
}

.site-footer .gb-container-77b04b02 > .gb-inside-container {
