document.addEventListener('DOMContentLoaded', function() {
  let dropdownContainers = document.querySelectorAll('.dropdown-container');

  dropdownContainers.forEach(function(container) {
    let expandBtn = container.querySelector('.expand-button');
    let expandBtnMobile = container.querySelector('.expand-button-mobile');
    let mobileArrow = container.querySelector('.mobile-arrow');
    let content = container.querySelector('.expand-content');
	let titleContainerMobile = container.querySelector('.title-container');
	let titleContainer = container.querySelector('.title-container-1');

	if (expandBtnMobile !== null) {
		titleContainerMobile.addEventListener('click', function(event) {
        event.stopPropagation();
	    toggleContentVisibility();
	  });
	}

	if (expandBtn !== null) {
		expandBtn.addEventListener('click', function(event) {
			event.stopPropagation();
			toggleContentVisibility();
		});
		titleContainer.addEventListener('click', function(event) {
			event.stopPropagation();
			toggleContentVisibility();
		});
	}

    function toggleContentVisibility() {
      content.classList.toggle('hidden-content');
      let contentHeight = content.scrollHeight;
      if (content.classList.contains('hidden-content')) {
        content.style.maxHeight = '0';
        if (expandBtnMobile !== null) {
          expandBtnMobile.innerHTML = 'Tap to expand';
          mobileArrow.innerHTML = '<strong>V</strong>';
        }
        if (expandBtn !== null) {
          if (expandBtn.classList.contains('outer')) {
			  expandBtn.innerHTML = 'Click to expand <strong>V</strong>';
		  } else {
			  expandBtn.innerHTML = '<strong>V</strong>';
		  }
        }
      } else {
        content.style.maxHeight = contentHeight + 'px';
        if (expandBtnMobile !== null) {
          expandBtnMobile.innerHTML = 'Tap to collapse';
          mobileArrow.innerHTML = '<strong>Ʌ</strong>';
        }
        if (expandBtn !== null) {
          if (expandBtn.classList.contains('outer')) {
			  expandBtn.innerHTML = 'Click to collapse <strong>Ʌ</strong>';
		  } else {
			  expandBtn.innerHTML = '<strong>Ʌ</strong>';
		  }
        }
      }
      updateParentMaxHeight(container, contentHeight);
    }
  });

  function updateParentMaxHeight(container, heightChange) {
    let parent = container.parentElement.closest('.dropdown-container');
    while (parent) {
      let parentContent = parent.querySelector('.expand-content');
      if (parentContent) {
        parentContent.style.maxHeight = (parentContent.scrollHeight + heightChange) + 'px';
      }
      parent = parent.parentElement.closest('.dropdown-container');
    }
  }
});

document.addEventListener("DOMContentLoaded", function() {
	
	const scrollers = document.querySelectorAll(".scroller");

	function addAnimation() {
// 		console.log("Animation Started");
		scrollers.forEach((scroller) => {
			const isAnimated = scroller.getAttribute("data-animated");
// 			console.log("Scroller animation status:", scroller, isAnimated);

			if (!isAnimated) {
				// Add data-animated="true" to every `.scroller` on the page
				scroller.setAttribute("data-animated", "true");
// 				console.log("Set data-animated for scroller", scroller);

				// Make an array from the elements within `.scroller-inner`
				const scrollerInner = scroller.querySelector(".scroller__inner");
				if (!scrollerInner) {
// 					console.log("No scroller__inner found within scroller", scroller);
					return;
				}

				const scrollerContent = Array.from(scrollerInner.children);
// 				console.log("Scroller content found:", scrollerContent);

				// For each item in the array, clone it
				// add aria-hidden to it
				// add it into the `.scroller-inner`
				scrollerContent.forEach((item) => {
					const duplicatedItem = item.cloneNode(true);
					duplicatedItem.setAttribute("aria-hidden", "true");

					// Ensure the duplicated item is visible
					if (duplicatedItem.tagName === "IMG") {
						duplicatedItem.style.opacity = 1;
						// Remove lazy-loading attributes if necessary
						duplicatedItem.removeAttribute("loading");
					}

					scrollerInner.appendChild(duplicatedItem);
// 					console.log("Duplicated item added to scroller-inner", duplicatedItem);
				});
			} else {
// 				console.log("Scroller already animated", scroller);
			}
		});
	}

	if (window.screen.width > 768) {
		addAnimation();
	} else {
		window.addEventListener("load", function() {
			addAnimation();
		});
	}
});

