			});
		});
});

document.addEventListener("DOMContentLoaded", () => {
  const awards = document.querySelectorAll(".awards-wrapper");
  const paddingBelowLastItem = 150; // Adjust to your padding

  function getOffsetTop(el) {
    let offset = 0;
    while (el) {
      offset += el.offsetTop;
      el = el.offsetParent;
    }
    return offset;
  }

  function onScroll() {
    if (window.innerWidth < 1024) {
      // Reset image positions below 1024px
      awards.forEach(wrapper => {
        const img = wrapper.querySelector("img");
        if (img) {
          img.style.position = "";
          img.style.top = "";
        }
      });
      return;
    }

    const scrollY = window.scrollY;

    awards.forEach(wrapper => {
      const img = wrapper.querySelector("img");
      if (!img) return;

      const loopItems = wrapper.querySelectorAll(".gb-loop-item");
      if (!loopItems.length) return;

      const lastItem = loopItems[loopItems.length - 1];

      const wrapperTop = getOffsetTop(wrapper);
      const lastItemTop = getOffsetTop(lastItem);

      let offsetInside = scrollY - wrapperTop;
      if (offsetInside < 0) offsetInside = 0;

      const maxOffset = lastItemTop - wrapperTop - paddingBelowLastItem;

      if (offsetInside > maxOffset) offsetInside = maxOffset;

      img.style.position = "relative";
      img.style.top = offsetInside + "px";
    });
  }

  window.addEventListener("scroll", onScroll);
  window.addEventListener("resize", onScroll);

  // Run once on load
  onScroll();
});

document.addEventListener('DOMContentLoaded', () => {
  const menu = document.getElementById('primary-menu');
  const menuToggle = document.querySelector('.menu-toggle');

  if (!menu || !menuToggle) return;

  menu.addEventListener('click', (e) => {
    const link = e.target.closest('a');

    // No link clicked? Bail.
    if (!link) return;

    // Ignore submenu toggle buttons
    if (e.target.closest('.submenu-toggle')) return;

    // Close the mobile menu
    menuToggle.click();
  });
});

