<script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/gsap.min.js"></script>
<script>
const tracks = gsap.utils.toArray(".slider-track");
const duration = 60;

const master = gsap.timeline({ repeat: -1 });

tracks.forEach((track, i) => {
master.to(track, {
x: "-100%",
ease: "linear",
duration: duration,
repeat: 0,
}, i * (duration / tracks.length));
});

</script>

<style>
.slider-container {
overflow: hidden;
width: 100%;
height: 60px;
}

.slider-track {
display: flex;
}

.slider-track img {
height: 60px;
margin-right: 2rem;
flex-shrink: 0;
}
</style>

