<script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/gsap.min.js"></script>
<script>
const tracksCustomers = gsap.utils.toArray(".slider-track-customers");
const durationCustomers = 60;

const masterCustomers = gsap.timeline({ repeat: -1 });

tracksCustomers.forEach((track, i) => {
  masterCustomers.to(track, {
    x: "-100%",
    ease: "linear",
    duration: durationCustomers,
    repeat: 0,
  }, i * (durationCustomers / tracksCustomers.length));
});

</script>

<style>
  .slider-container-customers {
    overflow: hidden;
    width: 100%;
    height: 60px;
  }

  .slider-track-customers {
    display: flex;
  }

  .slider-track-customers img {
    height: 60px;
    margin-right: 2rem;
    flex-shrink: 0;
  }
</style>


